-- expand-only: support is server mediated. No support content is exposed through PostgREST or Realtime.
create table private.support_team_members(user_id uuid primary key references public.profiles(id),first_name text not null default '' check(length(first_name)<=50),can_manage_team boolean not null default false,can_execute_privacy boolean not null default false,notification_mode text not null default 'in_app' check(notification_mode in('in_app','email','digest')),updated_at timestamptz not null default now());
create table private.support_team_roles(user_id uuid not null references public.profiles(id),role text not null check(role in('tournament','chat','game','platform')),granted_by uuid not null references public.profiles(id),granted_at timestamptz not null default now(),reason text not null,revoked_at timestamptz,primary key(user_id,role));
create table private.support_topics(id text primary key,name text not null,description text not null default '',roles text[] not null,protected_kind text check(protected_kind in('privacy','security','complaint','appeal','illegal','triage')),active boolean not null default true,sort_order integer not null default 0,default_priority text not null default 'normal' check(default_priority in('normal','high','urgent')),response_hours integer not null default 48 check(response_hours between 1 and 720),required_fields text[] not null default '{}',notification_mode text not null default 'in_app' check(notification_mode in('in_app','email','digest')),created_at timestamptz not null default now(),check(roles<@array['tournament','chat','game','platform']::text[]),check('platform'=any(roles)),check(protected_kind is null or protected_kind='appeal' and roles<@array['game','platform']::text[] or protected_kind<>'appeal' and roles=array['platform']::text[]));
