create table private.support_tickets(id uuid primary key default gen_random_uuid(),number bigint generated always as identity unique,requester_id uuid references public.profiles(id),guest_email text,guest_name text,guest_verified_at timestamptz,topic_id text not null references private.support_topics(id),title text not null check(length(title) between 3 and 180),status text not null default 'new' check(status in('new','in_progress','waiting_player','waiting_team','resolved','closed')),priority text not null default 'normal' check(priority in('normal','high','urgent')),assigned_to uuid references public.profiles(id),acl_roles text[] not null,protected_kind text,context jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),last_public_at timestamptz not null default now(),closed_at timestamptz,first_staff_reply_at timestamptz,reminded_at timestamptz,retention_hold_until timestamptz,check(requester_id is not null or guest_email is not null));
create index support_ticket_queue on private.support_tickets(status,updated_at);
create index support_ticket_requester on private.support_tickets(requester_id,updated_at);
create table private.support_messages(id uuid primary key default gen_random_uuid(),ticket_id uuid not null references private.support_tickets(id) on delete cascade,author_id uuid references public.profiles(id),author_kind text not null check(author_kind in('requester','staff','system')),first_name text,team_role text,visibility text not null default 'public' check(visibility in('public','internal')),body text not null check(length(body) between 1 and 12000),created_at timestamptz not null default now());
create index support_message_ticket on private.support_messages(ticket_id,created_at,id);
create table private.support_exclusions(ticket_id uuid not null references private.support_tickets(id) on delete cascade,user_id uuid not null references public.profiles(id),reason text not null,created_by uuid references public.profiles(id),created_at timestamptz not null default now(),primary key(ticket_id,user_id));
create table private.support_followers(ticket_id uuid not null references private.support_tickets(id) on delete cascade,user_id uuid not null references public.profiles(id),primary key(ticket_id,user_id));
create table private.support_reads(ticket_id uuid not null references private.support_tickets(id) on delete cascade,reader_key text not null,read_at timestamptz not null default now(),primary key(ticket_id,reader_key));
create table private.support_events(id uuid primary key default gen_random_uuid(),ticket_id uuid not null references private.support_tickets(id) on delete cascade,actor_id uuid references public.profiles(id),kind text not null,data jsonb not null default '{}',reason text,created_at timestamptz not null default now());
create table private.support_requests(actor_key text not null,scope text not null,request_key uuid not null,payload_hash text not null,response jsonb not null,created_at timestamptz not null default now(),primary key(actor_key,scope,request_key));
create table private.support_guest_verifications(id uuid primary key default gen_random_uuid(),ticket_id uuid not null references private.support_tickets(id) on delete cascade,token_hash text not null unique,expires_at timestamptz not null,used_at timestamptz,created_at timestamptz not null default now());
create table private.support_guest_sessions(id uuid primary key default gen_random_uuid(),ticket_id uuid not null references private.support_tickets(id) on delete cascade,token_hash text not null unique,expires_at timestamptz not null,revoked_at timestamptz,created_at timestamptz not null default now());
create table private.support_templates(id uuid primary key default gen_random_uuid(),topic_id text references private.support_topics(id),name text not null,body text not null check(length(body) between 1 and 12000),active boolean not null default true,updated_at timestamptz not null default now());
create table private.support_attachments(id uuid primary key default gen_random_uuid(),ticket_id uuid not null references private.support_tickets(id) on delete cascade,message_id uuid not null references private.support_messages(id) on delete cascade,uploaded_by uuid references public.profiles(id),name text not null,mime text not null check(mime in('image/png','image/jpeg','image/webp','application/pdf')),bytes integer not null check(bytes between 1 and 10485760),checksum text not null,data bytea not null,scan_status text not null default 'pending' check(scan_status in('pending','clean','rejected','error')),scan_attempts integer not null default 0,scan_after timestamptz not null default now(),scan_locked_until timestamptz,scan_error text,scanned_at timestamptz,created_at timestamptz not null default now());
create index support_attachment_scan on private.support_attachments(scan_after) where scan_status in('pending','error');
-- Service-only functions deliberately use invoker privileges and a fixed search path.
create function private.support_roles_for(p_user uuid) returns text[] language sql stable security invoker set search_path='' as $$
 select coalesce(array_agg(distinct role),'{}'::text[]) from (
 select r.role from private.support_team_roles r join public.profiles p on p.id=r.user_id and p.status='active' where r.user_id=p_user and r.revoked_at is null
 union select 'platform' from public.user_roles r join public.profiles p on p.id=r.user_id and p.status='active' where r.user_id=p_user and r.role in('owner','admin') and r.revoked_at is null
 ) s
$$;
create function private.support_can_staff(p_user uuid,p_ticket uuid) returns boolean language sql stable security invoker set search_path='' as $$
 select exists(select 1 from private.support_tickets t join private.support_topics tp on tp.id=t.topic_id where t.id=p_ticket and (t.requester_id is not null or t.guest_verified_at is not null or t.protected_kind in('privacy','illegal','triage')) and not exists(select 1 from private.support_exclusions e where e.ticket_id=t.id and e.user_id=p_user) and not exists(select 1 from public.sanctions s where s.target_id=p_user and s.room_id is null and s.kind='suspend' and s.starts_at<=now() and s.ends_at>now() and s.revoked_at is null) and exists(select 1 from unnest(private.support_roles_for(p_user)) r where r=any(t.acl_roles) and r=any(tp.roles)))
$$;
revoke all on function private.support_roles_for(uuid),private.support_can_staff(uuid,uuid) from public,anon,authenticated;
grant execute on function private.support_roles_for(uuid),private.support_can_staff(uuid,uuid) to dartspoint_app;
do $$ declare tbl text; begin foreach tbl in array array['support_team_members','support_team_roles','support_topics','support_tickets','support_messages','support_exclusions','support_followers','support_reads','support_events','support_requests','support_guest_verifications','support_guest_sessions','support_templates','support_attachments'] loop
 execute format('alter table private.%I enable row level security',tbl);
 execute format('revoke all on private.%I from public,anon,authenticated',tbl);
 execute format('grant select,insert,update,delete on private.%I to dartspoint_app',tbl);
 execute format('create policy support_backend on private.%I for all to dartspoint_app using(true) with check(true)',tbl);
 end loop; end $$;
grant usage,select on sequence private.support_tickets_number_seq to dartspoint_app;
revoke update,delete on private.support_events from dartspoint_app;
